import{_ as t,o,c as a,ah as n}from"./chunks/framework.DDXs_i7t.js";const m=JSON.parse('{"title":"Research: The ÖVP Donation List (Heidi Goëss-Horten)","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/oevp-spendenliste-details.md","filePath":"en/recherche/oevp-spendenliste-details.md"}'),i={name:"en/recherche/oevp-spendenliste-details.md"};function r(s,e,l,h,u,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="research-the-ovp-donation-list-heidi-goess-horten" tabindex="-1">Research: The ÖVP Donation List (Heidi Goëss-Horten) <a class="header-anchor" href="#research-the-ovp-donation-list-heidi-goess-horten" aria-label="Permalink to &quot;Research: The ÖVP Donation List (Heidi Goëss-Horten)&quot;">​</a></h1><p><strong>&quot;Pointillism of Capital&quot; – How 931,000 Euros became invisible to the Court of Audit.</strong></p><p>One of the central motifs in Part 4 of our mockumentary is the &quot;Rain of Gold&quot; – the massive party donations from Heidi Goëss-Horten to the ÖVP in 2018 and 2019. What appears on the surface like civic engagement turns out on closer inspection to be a masterpiece of bureaucratic concealment, also known as &quot;donation splitting.&quot;</p><hr><h2 id="the-raw-numbers" tabindex="-1">The Raw Numbers <a class="header-anchor" href="#the-raw-numbers" aria-label="Permalink to &quot;The Raw Numbers&quot;">​</a></h2><p>Heidi Horten was by far the largest single donor to the ÖVP federal party in the years leading up to the tightening of the Political Parties Act.</p><h3 id="_1-total-volume-2018–2019" tabindex="-1">1. Total Volume (2018–2019) <a class="header-anchor" href="#_1-total-volume-2018–2019" aria-label="Permalink to &quot;1. Total Volume (2018–2019)&quot;">​</a></h3><p>A total of <strong>931,000 Euros</strong> flowed from Heidi Horten to the ÖVP.</p><ul><li><strong>Year 2018:</strong> 588,000 Euros</li><li><strong>Year 2019 (until June):</strong> 343,000 Euros</li></ul><h3 id="_2-the-method-splitting-into-49-000-euro-tranches" tabindex="-1">2. The Method: Splitting into 49,000-Euro Tranches <a class="header-anchor" href="#_2-the-method-splitting-into-49-000-euro-tranches" aria-label="Permalink to &quot;2. The Method: Splitting into 49,000-Euro Tranches&quot;">​</a></h3><p>The unique aspect of these donations was not just the amount, but the method of transfer. The sums were consistently divided into tranches of <strong>49,000 Euros</strong> each.</p><ul><li><strong>The Reason:</strong> According to the legal situation at the time, donations only had to be reported immediately to the Court of Audit and published by it from a single amount of <strong>50,000 Euros</strong>.</li><li><strong>The Effect:</strong> By choosing 49,000 Euros, the donations remained hidden from the public until the annual accountability statement. The ÖVP only had to disclose these donations prematurely in August 2019 – under the massive pressure of the Ibiza Affair.</li></ul><hr><h2 id="political-and-legal-consequences" tabindex="-1">Political and Legal Consequences <a class="header-anchor" href="#political-and-legal-consequences" aria-label="Permalink to &quot;Political and Legal Consequences&quot;">​</a></h2><p>The &quot;Horten Case&quot; was the main trigger for a historic reform of the Austrian Political Parties Act in July 2019 (the so-called &quot;Anti-Corruption Package&quot;).</p><h3 id="key-changes" tabindex="-1">Key Changes: <a class="header-anchor" href="#key-changes" aria-label="Permalink to &quot;Key Changes:&quot;">​</a></h3><ul><li><strong>Immediate Reporting Requirement:</strong> Donations must now be reported immediately from an amount of <strong>2,500 Euros</strong>.</li><li><strong>Donation Cap:</strong> A single donor may now only donate a maximum of <strong>7,500 Euros</strong> per year in total to a party. A sum of 931,000 Euros would be completely illegal today.</li><li><strong>Audit Competence:</strong> The Court of Audit was given significantly stronger enforcement rights to audit party finances directly.</li></ul><hr><h2 id="significance-for-the-horten-mystery" tabindex="-1">Significance for &quot;The Horten Mystery&quot; <a class="header-anchor" href="#significance-for-the-horten-mystery" aria-label="Permalink to &quot;Significance for &quot;The Horten Mystery&quot;&quot;">​</a></h2><p>In our film, the donation list serves as a bridge between Helmut Horten&#39;s historical &quot;market consolidation&quot; and his widow&#39;s modern &quot;policy design.&quot;</p><ul><li><strong>Satirical Motif:</strong> We show the 49,000-euro transfers as &quot;artistic dots&quot; (pointillism), which only reveal the true picture of political influence from a distance.</li><li><strong>The Moral:</strong> While Helmut Horten accumulated wealth in the 1930s with the blessing of the state, Heidi Horten used her wealth to ensure that the blessing of the state (in the form of political goodwill) was maintained.</li></ul><hr><p><em>Sources: Reports of the Court of Audit (2019), analyses by kurier.at, kontrast.at, and profil.at on party financing.</em></p>',23)])])}const g=t(i,[["render",r]]);export{m as __pageData,g as default};
